html:
{% if letter_head %}{{ letter_head }}{% endif %}
{% set amounts = not doc.get('print_without_amount') %}
<div class="center"><h3>{{ (doc.select_print_heading or (_('Credit Note') if doc.get('is_return') else _(doc.doctype))) | e }}</h3><b>{{ (doc.company) | e }}</b></div>
{% if doc.docstatus == 0 %}<div class="warning center">DRAFT — NOT POSTED</div>{% endif %}
<p><b>{{ (_('Receipt No')) | e }}:</b> {{ (doc.name) | e }}<br><b>{{ (_('Sales Person')) | e }}:</b> {{ (doc.owner) | e }}<br><b>{{ (_('Customer')) | e }}:</b> {{ (doc.customer_name or doc.customer) | e }}<br><b>{{ (_('Date')) | e }}:</b> {{ (doc.get_formatted('posting_date')) | e }}<br><b>{{ (_('Time')) | e }}:</b> {{ (doc.get_formatted('posting_time')) | e }}<br>{% if doc.get('set_warehouse') %}<b>{{ (_('Shipper')) | e }}:</b> {{ (doc.set_warehouse) | e }}<br>{% endif %}{% if doc.get('po_no') %}<b>{{ (_('Customer PO')) | e }}:</b> {{ (doc.po_no) | e }}<br>{% endif %}{% if doc.get('return_against') %}<b>{{ (_('Return against')) | e }}:</b> {{ (doc.return_against) | e }}<br>{% endif %}</p><hr>
<table><thead><tr><th>{{ (_('Item')) | e }}</th><th class="right">{{ (_('Qty')) | e }}</th>{% if amounts %}<th class="right">{{ (_('Amount')) | e }}</th>{% endif %}</tr></thead><tbody>{% for item in doc.items %}<tr><td>{{ (item.item_code) | e }}{% if item.item_name != item.item_code %}<br>{{ (item.item_name) | e }}{% endif %}{% if item.get('batch_no') %}<br>{{ (_('Batch')) | e }}: {{ (item.batch_no) | e }}{% endif %}{% if item.get('serial_no') %}<br>{{ (_('Serial')) | e }}: {{ (item.serial_no | replace('
', ', ')) | e }}{% endif %}</td><td class="right">{{ (item.get_formatted('qty')) | e }} {{ (item.uom or item.stock_uom) | e }}{% if amounts %}<br>@ {{ (item.get_formatted('rate')) | e }}{% endif %}</td>{% if amounts %}<td class="right">{{ (item.get_formatted('amount')) | e }}</td>{% endif %}</tr>{% endfor %}</tbody></table><hr>
{% if amounts %}<table><tbody><tr><td>{{ (_('Total Excl. Tax') if doc.flags.show_inclusive_tax_in_print else _('Total')) | e }}</td><td class="right">{{ (doc.get_formatted('net_total' if doc.flags.show_inclusive_tax_in_print else 'total')) | e }}</td></tr>{% for row in doc.get('taxes') or [] %}{% if not row.included_in_print_rate or doc.flags.show_inclusive_tax_in_print %}<tr><td>{{ (row.description) | e }}{% if '%' not in row.description %} @ {{ (row.rate) | e }}%{% endif %}</td><td class="right">{{ (row.get_formatted('tax_amount', doc)) | e }}</td></tr>{% endif %}{% endfor %}{% if doc.discount_amount %}<tr><td>{{ (_('Discount')) | e }}</td><td class="right">{{ (doc.get_formatted('discount_amount')) | e }}</td></tr>{% endif %}<tr><td><b>{{ (_('Grand Total')) | e }}</b></td><td class="right"><b>{{ (doc.get_formatted('grand_total')) | e }}</b></td></tr>{% if doc.rounded_total %}<tr><td>{{ (_('Rounded Total')) | e }}</td><td class="right">{{ (doc.get_formatted('rounded_total')) | e }}</td></tr>{% endif %}{% for row in doc.get('payments') or [] %}<tr><td>{{ (row.mode_of_payment) | e }}</td><td class="right">{{ (row.get_formatted('amount', doc)) | e }}</td></tr>{% endfor %}{% if doc.get('paid_amount') %}<tr><td>{{ (_('Paid Amount')) | e }}</td><td class="right">{{ (doc.get_formatted('paid_amount')) | e }}</td></tr>{% endif %}{% if doc.get('change_amount') %}<tr><td>{{ (_('Change Amount')) | e }}</td><td class="right">{{ (doc.get_formatted('change_amount')) | e }}</td></tr>{% endif %}</tbody></table>{% endif %}
{% if doc.get('custom_einvoice_qr') %}<hr><p class="center"><b>{{ (_('e-Invoice QR Code')) | e }}</b></p><img class="qr" src="{{ doc.get('custom_einvoice_qr') | e }}"><p class="center"><small>{{ (_('Scan to verify this e-Invoice')) | e }}</small></p>{% endif %}
<hr><div>{{ doc.terms or '' }}</div><p class="center">{{ (_('Thank you')) | e }}</p><small>E&amp;O.E. {{ (_('This is a computer generated document.')) | e }}</small>
